// English word lists for the word games (Spelling Bee, Boggle).
// Built from SCOWL (size 50, American + common) filtered by word frequency, with
// offensive words removed. Packed: each word is <digits: letters shared with the
// previous word><rest>. Words.common is the everyday list (puzzle answers);
// Words.extra adds rarer dictionary words that Boggle also accepts.
(function () {
  function unpack(s) { var out = [], prev = '', re = /(\d)([a-z]+)/g, m; while ((m = re.exec(s))) { prev = prev.slice(0, +m[1]) + m[2]; out.push(prev); } return out; }
  var C = '';
  var E = '';
  var cache = {};
  window.Words = {
    common: function () { return cache.c || (cache.c = unpack(C)); },
    extra: function () { return cache.e || (cache.e = unpack(E)); }
  };
})();
